from qb import q, write

ENT = ["backend-developer", "full-stack-developer", "python-developer"]
ITEMS = [
    q("oop", "easy", ["oop-pillars"], "Explain abstraction and encapsulation and how they differ, using an ATM or bank account as the example.", "Abstraction shows only what a user needs, such as withdraw and check balance, and hides how it works. Encapsulation bundles data with the methods that protect it, so the balance cannot be changed except through valid operations.", ["Abstraction hides complexity", "Encapsulation protects state", "Different goals, work together"], ["Which access modifiers support encapsulation in your language?"]),
    q("oop", "medium", ["solid"], "What do the SOLID principles stand for, and give a practical example of the single responsibility principle.", "SOLID is single responsibility, open/closed, Liskov substitution, interface segregation and dependency inversion. Single responsibility means a class has one reason to change, so an invoice class should calculate totals while a separate class prints or emails it.", ["Name the five principles", "One reason to change", "Split calculation from printing"], ["How does dependency inversion make testing easier?"]),
    q("oop", "medium", ["design-patterns"], "Explain the singleton and factory patterns and one risk of overusing a singleton.", "A singleton ensures one shared instance, such as a configuration object. A factory creates objects without the caller naming the concrete class. Singletons act like global state, which makes code harder to test and can hide dependencies.", ["Singleton: one instance", "Factory: hides the concrete class", "Singleton is hidden global state"], ["How would you test code that depends on a singleton?"]),
    q("sql", "easy", ["keys", "normalisation"], "What are primary keys and foreign keys, and what is normalisation for?", "A primary key uniquely identifies each row and a foreign key points to a primary key in another table to link records. Normalisation splits data into related tables to avoid duplicate data and update anomalies.", ["Primary key is unique and not null", "Foreign key enforces links", "Normalisation removes duplication"], ["When might you deliberately denormalise?"]),
    q("sql", "medium", ["transactions", "acid"], "What does ACID mean and what is a transaction rollback used for?", "ACID is atomicity, consistency, isolation and durability. A transaction groups steps so they all succeed or none do, and a rollback undoes the whole group when a step fails, for example when a transfer debits one account but cannot credit the other.", ["Four ACID properties", "All or nothing", "Rollback on failure"], ["What is a dirty read and which isolation level prevents it?"]),
    q("sql", "medium", ["joins", "subqueries"], "Write the idea of a query to list employees who earn more than the average salary of their own department.", "Compute each department's average, either with a correlated subquery or by joining to a grouped subquery, and keep employees whose salary is greater than that value. A window function AVG(salary) OVER (PARTITION BY department) is another clean option.", ["Per-department average", "Subquery or join or window function", "Compare each employee salary"], ["Which version would you prefer for a large table and why?"]),
    q("sql", "hard", ["indexes", "query-plans"], "Why might a query not use an existing index, and how would you confirm and fix it?", "An index can be ignored when a function or type conversion wraps the column, when the filter returns most rows, or when statistics are outdated. Check the plan with EXPLAIN, rewrite the condition so the column is bare, and update statistics or adjust the index.", ["Functions on the column block the index", "Low selectivity", "Check EXPLAIN and rewrite"], ["What is a covering index?"]),
    q("os", "easy", ["processes", "threads"], "What is the difference between a process and a thread?", "A process is a running program with its own memory space, while threads are lighter units inside a process that share its memory. Threads communicate easily but need care with shared data; processes are isolated but heavier.", ["Own memory vs shared memory", "Threads are lighter", "Isolation vs easy sharing"], ["What problems can shared memory between threads cause?"]),
    q("os", "medium", ["deadlock"], "What is a deadlock, what conditions cause it and how can you avoid it?", "A deadlock is when processes wait on each other's resources forever. It needs mutual exclusion, hold and wait, no preemption and circular wait; avoid it by always acquiring locks in the same order, using timeouts or avoiding holding one lock while waiting for another.", ["Circular waiting forever", "Four necessary conditions", "Lock ordering and timeouts"], ["Give a real example of two threads deadlocking."]),
    q("os", "medium", ["memory"], "Explain virtual memory and paging in simple terms.", "Virtual memory gives each process its own address space that the operating system maps to physical memory in fixed-size pages, moving rarely used pages to disk when memory is short. This isolates processes and lets programs use more memory than physically installed, at the cost of slowdowns when swapping.", ["Own address space per process", "Pages mapped to frames", "Swapping to disk is slow"], ["What is thrashing?"]),
    q("networks", "easy", ["http", "tcp"], "What happens, step by step, when you type a URL into a browser and press Enter?", "The browser resolves the domain through DNS, opens a TCP connection and a TLS session for HTTPS, sends an HTTP request, receives the response, then parses the HTML and loads further resources such as scripts and images.", ["DNS lookup", "TCP and TLS connection", "HTTP request and rendering"], ["Where could caching speed this up?"]),
    q("networks", "medium", ["tcp-udp"], "Compare TCP and UDP and give a use case for each.", "TCP is connection-based, reliable and ordered, suitable for web pages and file transfer. UDP is connectionless with no delivery guarantee but lower delay, suitable for live video, voice and games where late data is useless.", ["TCP reliable and ordered", "UDP fast, no guarantee", "Use cases for each"], ["How does TCP detect and recover lost packets?"]),
    q("software-engineering", "easy", ["sdlc"], "Explain the software development life cycle and how Agile differs from the waterfall model.", "The cycle covers requirements, design, development, testing, deployment and maintenance. Waterfall completes each phase in order before the next, while Agile delivers in short iterations with regular feedback and changing requirements.", ["Phases of the cycle", "Waterfall is sequential", "Agile is iterative with feedback"], ["Which would you choose when requirements are unclear?"]),
    q("software-engineering", "medium", ["testing"], "What is the difference between unit, integration and system testing and what is regression testing?", "Unit tests check one small piece in isolation, integration tests check that parts work together, and system tests check the whole application against requirements. Regression testing reruns tests after a change to confirm old behaviour still works.", ["Three levels of testing", "Scope grows at each level", "Regression guards old behaviour"], ["Which tests should you automate first?"]),
    q("software-engineering", "medium", ["code-quality"], "What makes code maintainable? How do code reviews and refactoring help?", "Maintainable code is readable, consistent, modular, tested and documented where needed. Code reviews catch bugs and spread knowledge, and refactoring improves structure without changing behaviour, safely backed by tests.", ["Readable, modular, tested", "Reviews catch bugs and share knowledge", "Refactor with tests"], ["What would you check first when reviewing a pull request?"]),
    q("rest-api", "medium", ["rest", "authentication"], "How would you secure a REST API using tokens, and what is the difference between authentication and authorisation?", "The client logs in and receives a signed token such as a JWT that it sends with each request over HTTPS, and the server verifies the signature and expiry. Authentication proves who you are, authorisation decides what you may do, so each endpoint must also check permissions.", ["Signed token over HTTPS", "Verify signature and expiry", "Authentication vs authorisation"], ["How do you handle token expiry and revocation?"]),
    q("rest-api", "hard", ["api-design", "versioning"], "How do you evolve a public API without breaking existing clients?", "Add fields instead of removing or renaming them, version the API when a breaking change is needed, deprecate old versions with notice and keep tests for old contracts. Communicate changes and monitor usage before retiring anything.", ["Prefer additive changes", "Versioning for breaking changes", "Deprecation with notice"], ["Where would you put the version: URL or header?"]),
    q("dsa", "easy", ["arrays", "searching"], "Explain linear search and binary search, and what must be true before binary search works.", "Linear search checks items one by one in O(n). Binary search repeatedly halves a sorted list in O(log n), so the data must be sorted and support fast indexed access.", ["Linear O(n)", "Binary O(log n)", "Requires sorted data"], ["What happens to binary search if the list has duplicates?"]),
    q("dsa", "medium", ["stack", "queue"], "What is the difference between a stack and a queue? Give a real use for each.", "A stack is last in first out, used for undo history and function calls. A queue is first in first out, used for print jobs, task scheduling and breadth-first search.", ["LIFO vs FIFO", "Stack: undo, call stack", "Queue: scheduling, BFS"], ["How would you build a queue using two stacks?"]),
    q("dsa", "hard", ["trees", "recursion"], "How would you check whether a binary tree is a valid binary search tree?", "Recursively check each node against a valid range: all values in the left subtree must be below the node and all in the right above it. Pass narrowing minimum and maximum bounds down the tree, or check that an in-order traversal is strictly increasing.", ["Check against ranges, not just children", "Pass min and max bounds", "In-order must be increasing"], ["What is the time and space complexity?"]),
    q("devops", "easy", ["git", "ci"], "What is continuous integration and why do teams use it with Git?", "Continuous integration builds and tests every change automatically when it is pushed. It finds integration bugs early, keeps the main branch working and makes releases less risky.", ["Automatic build and test on push", "Find bugs early", "Keep main stable"], ["What would you put in a minimal pipeline?"], roles=ENT + ["frontend-developer"]),
    q("enterprise-scenario", "medium", ["performance"], "Scenario: a report page that worked in testing takes 40 seconds in production with real data. How do you approach it?", "Measure first to find whether time goes to the database, the application or the network, check the query plan and indexes, avoid loading unnecessary rows and fix the biggest bottleneck. Consider pagination, caching or precomputed summaries and verify the improvement.", ["Measure before changing", "Check the query and indexes", "Paginate, cache or precompute"], ["How would you stop this regression returning?"], kind="scenario"),
    q("enterprise-scenario", "medium", ["requirements"], "Scenario: a client keeps changing requirements in the middle of a sprint. What do you do?", "Clarify the business need, estimate the impact of the change, discuss trade-offs with the product owner and either schedule it for the next sprint or swap it for something of equal size. Record the decision so the team and client agree.", ["Clarify and estimate impact", "Trade off with the owner", "Record the decision"], ["How do you keep the team's commitment realistic?"], kind="scenario"),
    q("enterprise-scenario", "hard", ["data-migration"], "Scenario: you must move a live customer database to a new schema with minimal downtime. How do you plan it?", "Plan the mapping, take a backup, rehearse the migration on a copy, make changes backward compatible where possible and run old and new schemas side by side if needed. Prepare a rollback, validate counts and samples after migrating and choose a low-traffic window.", ["Backup and rehearsal", "Backward compatible steps and rollback", "Validate after migration"], ["How would you migrate data that keeps changing during the move?"], kind="scenario"),
    q("project", "easy", ["projects", "teamwork"], "Tell me about a project you worked on, ideally in a team. What was your role, how did you use Git and how did you handle a disagreement or a bug?", "A strong answer names the project and your exact role, explains how the team used branches and pull requests, and gives one concrete bug or disagreement with how it was resolved and what you learned.", ["Clear role and contribution", "Real use of Git workflow", "A concrete problem and its resolution"], ["What would you do differently next time?"], kind="scenario", roles=ENT + ["frontend-developer"]),
]


def build():
    return write("systems-limited", ENT, ITEMS)


if __name__ == "__main__":
    build()
